    /// <summary>
    /// 获取指定箱子的颜色数据
    /// </summary>
    public static List<ScrewColor> GetBoxColors(string boxName)
    {
        if (BoxColors.ContainsKey(boxName))
        {
            return BoxColors[boxName];
        }
        return null;
    }

